async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  let pending = "";
  let line = 1;
  let count = 0;

  function parseLine(text, lineNumber) {
    if (/^\s*$/.test(text)) return undefined;

    try {
      return JSON.parse(text);
    } catch (_) {
      const error = new Error("Invalid JSON line");
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }
  }

  async function deliverLine(text, lineNumber) {
    const value = parseLine(text, lineNumber);
    if (value === undefined && /^\s*$/.test(text)) return false;

    count++;
    return (await deliver(value, lineNumber)) === false;
  }

  try {
    while (true) {
      const chunk = await input.read();
      if (chunk === null) break;

      pending += decoder.decode(chunk, { stream: true });

      let index;
      while ((index = pending.indexOf("\n")) !== -1) {
        let text = pending.slice(0, index);
        pending = pending.slice(index + 1);

        if (text.endsWith("\r")) text = text.slice(0, -1);

        if (await deliverLine(text, line)) return count;
        line++;
      }
    }

    pending += decoder.decode();

    if (pending.length > 0) {
      if (await deliverLine(pending, line)) return count;
    }

    return count;
  } finally {
    await input.close();
  }
}
